import React, { useEffect, useState, useMemo } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import TabBar from "../../components/common/TabBar";
import api from "../../utils/api";

/* ======================================================
   TYPES
====================================================== */
type SelectedService = {
  _id: string;
  name: string;
  durationMinutes: number;
  priceBHD: number;
  description?: string;
};

type LocationState = {
  businessId: string;
  businessName: string;
  selectedServices: SelectedService[];
  totalDurationMinutes: number;
  totalPrice: number;
  isReschedule?: boolean;
  bookingId?: string;
};

type OperatingHours = {
  monday?: string;
  tuesday?: string;
  wednesday?: string;
  thursday?: string;
  friday?: string;
  saturday?: string;
  sunday?: string;
};

/* ======================================================
   COMPONENT
====================================================== */
const SelectDatePage: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const state = location.state as LocationState | undefined;

  /* HOOKS */
  const [date, setDate] = useState<string>("");
  const [slots, setSlots] = useState<string[]>([]);
  const [loadingSlots, setLoadingSlots] = useState(false);
  const [selectedTime, setSelectedTime] = useState("");
  const [operatingHours, setOperatingHours] = useState<OperatingHours | null>(null);
  const [loadingBusiness, setLoadingBusiness] = useState(false);

  /* Redirect if opened manually */
  useEffect(() => {
    if (!state) navigate("/home");
  }, [state, navigate]);

  if (!state) return null;

  const {
    businessId,
    businessName,
    selectedServices,
    totalDurationMinutes,
    totalPrice,
    isReschedule,
    bookingId,
  } = state;

  const today = new Date().toISOString().split("T")[0];

  /* Load business operating hours */
  useEffect(() => {
    const fetchBusiness = async () => {
      try {
        setLoadingBusiness(true);

        const res = await api.get(`/public/businesses/${businessId}`);

        if (res.data?.business?.operatingHours) {
          setOperatingHours(res.data.business.operatingHours as OperatingHours);
        }
      } catch (err) {
        console.error("Failed to load business hours", err);
      } finally {
        setLoadingBusiness(false);
      }
    };

    fetchBusiness();
  }, [businessId]);

  /* Fetch available slots */
  const fetchSlots = async (selectedDate: string) => {
    try {
      setLoadingSlots(true);
      setSlots([]);
      setSelectedTime("");

      const res = await api.get<string[]>(
        `/bookings/available-slots/${businessId}`,
        {
          params: {
            date: selectedDate,
            duration: totalDurationMinutes,
          },
        }
      );

      setSlots(res.data || []);
    } catch (err: any) {
      alert(err?.response?.data?.message || "Failed to load time slots.");
    } finally {
      setLoadingSlots(false);
    }
  };

  /* When user selects a date */
  const onDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;

    if (!value) {
      setDate("");
      setSlots([]);
      setSelectedTime("");
      return;
    }

    // Check if salon is closed on selected day
    if (operatingHours) {
      const jsDate = new Date(`${value}T00:00:00`);
      const dayIndex = jsDate.getDay();

      const dayKeys: (keyof OperatingHours)[] = [
        "sunday",
        "monday",
        "tuesday",
        "wednesday",
        "thursday",
        "friday",
        "saturday",
      ];

      const dayKey = dayKeys[dayIndex];
      const hours = operatingHours[dayKey];

      if (!hours || hours.toLowerCase() === "closed") {
        alert("Salon is closed today. Please choose another date.");

        // Reset
        setDate("");
        setSlots([]);
        setSelectedTime("");
        return;
      }
    }

    // Salon open → continue
    setDate(value);
    fetchSlots(value);
  };

  /* Continue */
  const handleNext = () => {
    if (!date || !selectedTime) {
      alert("Please select a date and time.");
      return;
    }

    navigate("/book/summary", {
      state: {
        businessId,
        businessName,
        selectedServices,
        totalDurationMinutes,
        totalPrice,
        date,
        time: selectedTime,
        isReschedule: !!isReschedule,
        bookingId,
      },
    });
  };

  /* ======================================================
     RENDER
  ====================================================== */
  return (
    <div style={{ backgroundColor: "#F1DEDE", minHeight: "100vh", paddingBottom: "40px" }}>
      <TabBar type="customer" />

      <div
        style={{
          width: "90%",
          maxWidth: "700px",
          margin: "40px auto 0 auto",
          backgroundColor: "#fff",
          borderRadius: "16px",
          padding: "24px",
          boxShadow: "0 4px 12px rgba(0,0,0,0.15)",
        }}
      >
        <h2 style={{ fontSize: "24px", fontWeight: 700 }}>
          {isReschedule ? "Reschedule Booking" : "Choose Date & Time"}
        </h2>

        <p style={{ marginTop: "4px", fontSize: "14px", color: "#555" }}>
          {businessName}
        </p>

        {/* DATE PICKER */}
        <div style={{ marginTop: "20px" }}>
          <label style={{ display: "block", marginBottom: "6px" }}>
            Select a date:
          </label>

          <input
            id="date"
            type="date"
            value={date}
            min={today}
            onChange={onDateChange}
            style={{
              padding: "10px",
              borderRadius: "8px",
              border: "1px solid #ccc",
              fontSize: "14px",
            }}
          />

          {loadingBusiness && (
            <p style={{ fontSize: "12px", color: "#777", marginTop: "4px" }}>
              Loading salon hours...
            </p>
          )}
        </div>

        {/* TIME SLOTS */}
        <div style={{ marginTop: "24px" }}>
          <h4 style={{ marginBottom: "10px" }}>Available time slots</h4>

          {loadingSlots && <p>Loading slots...</p>}

          {!loadingSlots && date && slots.length === 0 && (
            <p style={{ color: "#777" }}>No available slots for this date.</p>
          )}

          {!loadingSlots && slots.length > 0 && (
            <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
              {slots.map((slot) => (
                <button
                  key={slot}
                  onClick={() => setSelectedTime(slot)}
                  style={{
                    padding: "8px 12px",
                    borderRadius: "8px",
                    border:
                      selectedTime === slot
                        ? "2px solid #27374d"
                        : "1px solid #ddd",
                    backgroundColor:
                      selectedTime === slot ? "#27374d" : "#f9f9f9",
                    color: selectedTime === slot ? "#fff" : "#333",
                    cursor: "pointer",
                    fontSize: "13px",
                  }}
                >
                  {slot}
                </button>
              ))}
            </div>
          )}
        </div>

        {/* SUMMARY + NEXT */}
        <div
          style={{
            marginTop: "30px",
            paddingTop: "14px",
            borderTop: "1px solid #eee",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            flexWrap: "wrap",
            gap: "10px",
          }}
        >
          <div style={{ fontSize: "14px" }}>
            <div>
              {selectedServices.length} service
              {selectedServices.length > 1 ? "s" : ""} •{" "}
              {totalDurationMinutes} min
            </div>
            <div>
              Total: <strong>{totalPrice.toFixed(2)} BD</strong>
            </div>
          </div>

          <button
            onClick={handleNext}
            disabled={!date || !selectedTime}
            style={{
              padding: "10px 20px",
              borderRadius: "10px",
              border: "none",
              cursor: !date || !selectedTime ? "not-allowed" : "pointer",
              backgroundColor: !date || !selectedTime ? "#ccc" : "#27374d",
              color: "#fff",
              fontWeight: 600,
            }}
          >
            Next: Review
          </button>
        </div>
      </div>
    </div>
  );
};

export default SelectDatePage;
